self.KB_CONTENT["card:753120"]={"id":"card:753120","ty":"card","sourceId":"753120","title":"『立沖帳目指定結案開帳作業』的作業目的為何？","ver":"iGP","topic":"立沖帳目","keywords":["立沖帳目","結案","餘額","未結"],"y":"explain","answer":"2.X版更至3.X或以上版本，將之前未沖帳且未結案的立沖帳目做借貸金額沖帳，並將沖帳後資料作指定結案，並將餘額執行開帳作業。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
