self.KB_CONTENT["card:751360"]={"id":"card:751360","ty":"card","sourceId":"751360","title":"『科目/部門預算複製作業』中的『累加原目的預算金額』為何？","ver":"iGP","topic":"科目","keywords":["科目","編號","複製","預算"],"y":"other","answer":"* 若不累加原目的預算金額，則會先清除己存在目的預算編號+年度的預算資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
