self.KB_CONTENT["card:782834"]={"id":"card:782834","ty":"card","sourceId":"782834","title":"『E-BOM 用量資料建立』中的『生效日期 (MK011)』為何？","ver":"GP4以上","topic":"用量","keywords":["用量","元件","效日","一筆"],"y":"other","answer":"* 表示一主件之組成元件資料自此日期開始失效。* 輸入時系統預設上一筆生效日期。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
