self.KB_CONTENT["card:782971"]={"id":"card:782971","ty":"card","sourceId":"782971","title":"『銀行月統計維護作業』的作業重點有哪些？","ver":"GP4以上","topic":"銀行","keywords":["銀行","統計","人工","月底"],"y":"explain","answer":"■作業重點1.作業於『存款月底結轉作業』後自動產生，請勿人工自行維護。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
