self.KB_CONTENT["field:754187"]={"id":"field:754187","ty":"field","sourceId":"754187","title":"專案代號","ver":"iGP","topic":"","keywords":[],"job":"訂單變更單建立作業","code":"TF022","answer":"* 專採採生失效日控管。* [F2]專案代號資料查詢。* [F3]品號專案資料查詢。","file":"fields.jsonl"};
