self.KB_CONTENT["field:792286"]={"id":"field:792286","ty":"field","sourceId":"792286","title":"選擇列印狀態","ver":"GP4以上","topic":"","keywords":[],"job":"借支申請單憑證","code":"","answer":"* 區分為Y.已列印、N.未列印及全部。","file":"fields.jsonl"};
