self.KB_CONTENT["field:777575"]={"id":"field:777575","ty":"field","sourceId":"777575","title":".批號","ver":"GP4以上","topic":"","keywords":[],"job":"託外退貨單建立作業","code":"TL014","answer":"* 為退貨件之批號。* [F2]批號資料查詢，輸入時批號必須存在於批號單頭檔內。但不允許空白。","file":"fields.jsonl"};
