self.KB_CONTENT["field:784151"]={"id":"field:784151","ty":"field","sourceId":"784151","title":"預算科目","ver":"GP4以上","topic":"","keywords":[],"job":"資產採購變更作業","code":"TR018","answer":"* 採預算控管時，此欄位不可空白。* [F2]科目/部門預算資料查詢，並自動顯示科目名稱。* 預設上一筆。* [F3]科目預算耗用/可用餘額查詢。","file":"fields.jsonl"};
